#nullable enable // autogenerated

using System.Linq;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Grids;
using MVZ2Logic.Entities;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.leaveLilyPadWhenDestroyedWithProtector)]
    public class LeaveLilyPadWhenDestroyedWithProtector : EntityBehaviourDefinition
    {
        public LeaveLilyPadWhenDestroyedWithProtector(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_ENTITY_EJECT, PostEntityEjectCallback);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            LeaveLilyPadIfHasProtector(entity);
        }
        private void LeaveLilyPadIfHasProtector(Entity entity)
        {
            var tiles = entity.GetGridsToTake();
            foreach (var tile in tiles)
            {
                if (tile == null || tile.GetProtectorEntity() == null)
                    continue;

                var carriers = tile.GetLayerEntities(VanillaGridLayers.carrier);
                if (carriers.Any(e => e != entity))
                    continue;

                entity.SpawnWithParams(VanillaContraptionID.lilyPad, tile.GetEntityPosition());
            }
        }
        private void PostEntityEjectCallback(VanillaLevelCallbacks.PostEntityEjectParams args, CallbackResultVoid result)
        {
            var entity = args.entity;
            if (!entity.HasBehaviour(this))
                return;
            LeaveLilyPadIfHasProtector(entity);
        }
    }
}
